CREATE TABLE global_finance_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),daily_usd TEXT NOT NULL,monthly_usd TEXT NOT NULL,time_zone TEXT NOT NULL);
CREATE TABLE global_paid_operations(operation_id TEXT PRIMARY KEY,request_hash TEXT NOT NULL,provider TEXT NOT NULL,maximum_usd TEXT NOT NULL,proof_json TEXT NOT NULL,created_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('RESERVED','SUBMITTING','UNKNOWN','COMPLETED')),actual_usd TEXT,billing_reference TEXT,result_json TEXT);
CREATE TRIGGER global_paid_identity_immutable BEFORE UPDATE ON global_paid_operations WHEN NEW.operation_id!=OLD.operation_id OR NEW.request_hash!=OLD.request_hash OR NEW.provider!=OLD.provider OR NEW.maximum_usd!=OLD.maximum_usd OR NEW.proof_json!=OLD.proof_json OR NEW.created_at!=OLD.created_at BEGIN SELECT RAISE(ABORT,'GLOBAL_IDENTITY_IMMUTABLE'); END;
CREATE TRIGGER global_paid_no_delete BEFORE DELETE ON global_paid_operations BEGIN SELECT RAISE(ABORT,'GLOBAL_OPERATION_IMMUTABLE'); END;
CREATE TRIGGER global_paid_state BEFORE UPDATE ON global_paid_operations WHEN NOT(NEW.state=OLD.state OR OLD.state='RESERVED' AND NEW.state='SUBMITTING' OR OLD.state='SUBMITTING' AND NEW.state IN ('UNKNOWN','COMPLETED') OR OLD.state='UNKNOWN' AND NEW.state='COMPLETED') BEGIN SELECT RAISE(ABORT,'GLOBAL_TRANSITION_INVALID'); END;
CREATE UNIQUE INDEX global_paid_intent ON global_paid_operations(provider,request_hash);
CREATE TRIGGER global_paid_billing_immutable BEFORE UPDATE ON global_paid_operations WHEN OLD.actual_usd IS NOT NULL AND (NEW.actual_usd IS NOT OLD.actual_usd OR NEW.billing_reference IS NOT OLD.billing_reference) BEGIN SELECT RAISE(ABORT,'GLOBAL_BILLING_IMMUTABLE'); END;
CREATE TRIGGER global_paid_result_immutable BEFORE UPDATE ON global_paid_operations WHEN OLD.result_json IS NOT NULL AND NEW.result_json IS NOT OLD.result_json BEGIN SELECT RAISE(ABORT,'GLOBAL_RESULT_IMMUTABLE'); END;
